// RCC base address 0x4002 3800 - 0x4002 3BFF
// AHB1 offset 0x30

// GPIOD 0x4002 0C00 - 0x4002 0FFF
// GPIO Mode offset 0x00
// GPIO Output data offset 0x14

#include <stdint.h>
#include <stdint.h>

#if !defined(__SOFT_FP__) && defined(__ARM_FP)
  #warning "FPU is not initialized, but the project is compiling for an FPU. Please initialize the FPU before use."
#endif
void delay(uint32_t count) {
	for(uint32_t i = 0; i < count; i++);
}

int main(void)
{
	uint32_t *pClkCtrlReg = (uint32_t*)0x40023830;
	uint32_t *pPortDModeReg = (uint32_t*)0x40020C00;
	uint32_t *pPortDOutReg = (uint32_t*)0x40020C14;

	// 1. enable the clock for 3rd bit with mask value
	uint32_t temp = *pClkCtrlReg; // read operation
	temp = temp | 0x08; // modify
	*pClkCtrlReg = 0x08; // write

	// *pClkCrlReg |= (1 << 3);

	// 2. configure the mode as output, 25 and 24 position should be 01
	// a. clear the 24th and 25th bit positions (clear
	*pPortDModeReg &= 0xFCFFFFFF;

	// *pPortDModeReg &= ~(1 << 24);
	// *pPortDModeReg &= ~(1 << 25);

	// or even better
	// *pPortDModeReg &= ~(3 << 24);

	// b. make 24th bit position as 1 (SET)
	*pPortDModeReg |= 0x01000000;

	// *pPortDModeReg |= (1 << 24);

	// 3. SET 12 bit of the output data register to make I/O pin-12 as HIGH
	while(1){
		*pPortDOutReg |= 0x1000;
		// *pPortDOutReg |= (1 << 12);
		delay(800000);
		*pPortDOutReg &= ~0x1000;
		// *pPortDoutReg &= ~(1 << 12):
		delay(200000);
	}

}
